import { useDrag } from '@use-gesture/react'

const api = useSpringRef()
const [springs] = useSpring(() => ({
  ref: api,
  x: 0,
  config: { decay: true }
}))

const bind = useDrag(({ down, velocity: [vx], offset: [ox] }) => {
  if (down) {
    api.start({ x: ox, config: { tension: 300, friction: 30 } })
  } else {
    // Fling with decay based on release velocity
    api.start({
      x: ox + vx * 200,
      config: { decay: true, velocity: vx }
    })
  }
})

return <animated.div {...bind()} style={springs} />

